#!/usr/bin/env bash
# ADET_CLOCK deploy — Adet kartı Ciro ile aynı saate alındı (son ay + delta). FRONTEND-ONLY. CANLI /api/bi/kokpit'e DOKUNMAZ.
set -e
cd /opt/krb-assessment
KOKF=shells/kokpit2.html
[ -f "$KOKF" ] || { echo "HATA: $KOKF yok"; exit 1; }
cp "$KOKF" "$KOKF.bak.$(date +%s)"
printf '%s' '' | base64 -d > "$KOKF"
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== /api/bi/kokpit2 -> Adet artik Ciro ile ayni ay (Bu ay = Temmuz tek ay, ~6.254) + delta. =="
echo "== DONE =="
